package cn.zhuatech.csm.controller; import cn.zhuatech.csm.common.ApiResponse; import cn.zhuatech.csm.dto.CsmDto.*; import cn.zhuatech.csm.service.CsmService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('CSM_DIRECTOR','QUALITY','ADMIN')") public class CustomerSuccessAdminController {private final CsmService service;public CustomerSuccessAdminController(CsmService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<SuccessPlanView>> orders(){return ApiResponse.ok(service.successPlans());}}
